class Robot {
    #energy;

    constructor(initialEnergy) {
        this.#energy = initialEnergy;
    }

    recharge(amount) {
        this.#energy = Math.min(100, this.#energy + amount);
        return `Recharged! Energy: ${this.#energy}`;
    }

    performTask(cost) {
        if (this.#energy >= cost) {
            this.#energy -= cost;
            return `Task performed. Energy: ${this.#energy}`;
        } else {
            return `Not enough energy. Current energy: ${this.#energy}`;
        }
    }

    getEnergyLevel() {
        return this.#energy;
    }
}

